import {serve} from '@hono/node-server';import {serveStatic} from '@hono/node-server/serve-static';import {Hono} from 'hono';import {z} from 'zod';import {calculate,type RequestInput} from './logic.js';
declare const process:{env:Record<string,string|undefined>};const maxBodyBytes=16_384;const schema=z.object({transfer_tag:z.string(),folio_boxes:z.number().int(),atlas_tubes:z.number().int(),catalog_carts:z.number().int(),humidity_warning:z.boolean()}).strict();
const response=(value:unknown,status=200,headers:Record<string,string>={})=>{if(Object.keys(headers).some(name=>['content-length','content-type','connection','transfer-encoding','x-content-type-options'].includes(name.toLowerCase())))return new Response(JSON.stringify({error:'invalid_response_headers',detail:'server-owned response header'}),{status:500,headers:{'content-type':'application/json'}});return new Response(JSON.stringify(value),{status,headers:{'content-type':'application/json',...headers}})};const error=(code:string,status:number,detail:string)=>response({error:code,detail},status);const zero=(v:RequestInput,state:string)=>({transfer_tag:v.transfer_tag,volume_tally:0,relocation_effort:0,cart_allowance:0,shelved_effort:0,quarantined_effort:0,transfer_rounds:0,transfer_rating:0,transfer_phase:state});const decide=(v:RequestInput,headers:Headers)=>{if([v.folio_boxes,v.atlas_tubes,v.catalog_carts].some(item=>item<0))return response(zero(v,'invalid'),422,{'x-validation':'nonnegative'});if(v.catalog_carts===0&&v.folio_boxes+v.atlas_tubes>0)return response(zero(v,'invalid'),422,{'x-validation':'catalog_carts'});const body=calculate(v);return response(body,201,{'location':`/api/v10/archive-transfers/${v.transfer_tag}`,'x-transfer-phase':String(body.transfer_phase)});};
const app=new Hono();app.get('/status/archive-transfer-ready',()=>response({service:'Archive Transfer',ready:true}));app.post('/api/v10/archive-transfers',async context=>{const media=(context.req.header('content-type')??'').split(';',1)[0]!.trim().toLowerCase();if(media!=='application/json'&&!media.endsWith('+json'))return error('json_content_type_required',415,'expected application/json');const declared=context.req.header('content-length');if(declared&&(!/^\d+$/.test(declared)||Number(declared)>maxBodyBytes))return error('body_too_large',413,'request body exceeds 16384 bytes');const raw=await context.req.arrayBuffer();if(raw.byteLength>maxBodyBytes)return error('body_too_large',413,'request body exceeds 16384 bytes');try{const parsed=schema.safeParse(JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(raw)));if(!parsed.success)return error('invalid_json',400,parsed.error.message);return decide(parsed.data,context.req.raw.headers)}catch(caught){return error('invalid_json',400,String(caught))}});app.all('/api/*',context=>error('not_found',404,`no API route ${context.req.path}`));app.get('/parley.js',serveStatic({path:process.env.FULLSTACK_046_BROWSER??'./dist/logic.js'}));app.get('/*',serveStatic({root:'./public'}));serve({fetch:app.fetch,hostname:'127.0.0.1',port:Number(process.env.PARLEY_WEB_PORT)});

