export type RequestInput={transfer_tag:string;folio_boxes:number;atlas_tubes:number;catalog_carts:number;humidity_warning:boolean};export const score=(f:number,a:number,c:number,h:boolean)=>{const t=f+a,e=f*6+a*17+(h?c*3:0),x=c*43;return Math.min(e,x)+Math.max(e-x,0)*6+Math.trunc((t+4)/5)*7};export const calculate=(v:RequestInput)=>{const t=v.folio_boxes+v.atlas_tubes,e=v.folio_boxes*6+v.atlas_tubes*17+(v.humidity_warning?v.catalog_carts*3:0),a=v.catalog_carts*43,q=Math.max(e-a,0);return {transfer_tag:v.transfer_tag,volume_tally:t,relocation_effort:e,cart_allowance:a,shelved_effort:Math.min(e,a),quarantined_effort:q,transfer_rounds:Math.trunc((t+4)/5),transfer_rating:score(v.folio_boxes,v.atlas_tubes,v.catalog_carts,v.humidity_warning),transfer_phase:q===0?'shelved':v.humidity_warning?'humidity_hold':'routine_hold'}};export async function loadParley(){return {archive_transfer_rating:(a0:number,a1:number,a2:number,a3:boolean)=>BigInt(score(a0,a1,a2,a3))}}
